    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and p not in seen
                            and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        stack.append(p)
            objects.append((color, cells))

    # The 8 cells delimit a set of independent objects shifted right together.
    # Infer displacement for each object from the gap to the next object in its rows.
    markers = {cell for color, cells in objects if color == 8 for cell in cells}
    shapes = [(color, cells) for color, cells in objects if color != 8]
    placed = [(8, [cell]) for cell in markers]
    for color, cells in shapes:
        maxshift = min(w - 1 - c for _, c in cells)
        for dr, dc in cells:
            for other_color, other_cells in objects:
                if other_color == color and other_cells is cells:
                    continue
                for rr, cc in other_cells:
                    if rr == dr and cc > dc:
                        maxshift = min(maxshift, cc - dc - 1)
        moved = [(r, c + maxshift) for r, c in cells]
        placed.append((color, moved))

    out = [[0] * w for _ in range(h)]
    for color, cells in placed:
        for r, c in cells:
            out[r][c] = color
    return out", "exit_code": 0, "error": null}
